import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        details TEXT,
        ts DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_token(token):
    """Verify HMAC-based auth token"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    username, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return username
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Requires valid auth."""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    caller = verify_token(auth[7:])
    if not caller:
        return jsonify({'error': 'invalid token'}), 401

    # Get search parameters
    username = request.args.get('username', '')
    role = request.args.get('role', '')
    email = request.args.get('email', '')

    # Build query with filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if role:
        conditions.append(f"role = '{role}'")
    if email:
        conditions.append(f"email LIKE '%{email}%'")

    query = "SELECT id, username, email, role FROM users"
    if conditions:
        query += " WHERE " + " AND ".join(conditions)

    # Log the search action
    db = get_db()
    db.execute(
        "INSERT INTO audit_log (action, username, details) VALUES (?, ?, ?)",
        ('search', caller, query)
    )
    db.commit()

    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401
    caller = verify_token(auth[7:])
    if not caller:
        return jsonify({'error': 'invalid token'}), 401

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
